<div class="page-heading"><div><h1>Laporan</h1><p>Ringkasan data buku dan transaksi perpustakaan.</p></div></div>
<div class="row g-3 mb-4">
<div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-muted" style="font-size:11px">Judul Buku</div><div class="fs-3 fw-bold text-primary"><?= (int)$totalBuku ?></div></div></div></div>
<div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-muted" style="font-size:11px">Total Stok</div><div class="fs-3 fw-bold text-success"><?= (int)$totalStok ?></div></div></div></div>
<div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-muted" style="font-size:11px">Sedang Dipinjam</div><div class="fs-3 fw-bold text-warning"><?= (int)$totalDipinjam ?></div></div></div></div>
<div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-muted" style="font-size:11px">Sudah Kembali</div><div class="fs-3 fw-bold text-success"><?= (int)$totalKembali ?></div></div></div></div>
</div>
<div class="card"><div class="card-header bg-white"><strong>Riwayat Transaksi</strong></div><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>No</th><th>ID Peminjaman</th><th>NIM</th><th>Nama</th><th>Buku</th><th>Pinjam</th><th>Kembali</th><th>Status</th></tr></thead><tbody><?php if(empty($daftarPeminjaman)): ?><tr><td colspan="8" class="text-center empty-state">Belum ada transaksi.</td></tr><?php else:$no=1;foreach($daftarPeminjaman as $p): ?><tr><td><?= $no++ ?></td><td><?= htmlspecialchars($p['kode_peminjaman']) ?></td><td><?= htmlspecialchars($p['nim']) ?></td><td><?= htmlspecialchars($p['nama_anggota']) ?></td><td><?= htmlspecialchars($p['judul_buku']) ?></td><td><?= htmlspecialchars($p['tanggal_pinjam']) ?></td><td><?= htmlspecialchars($p['tanggal_kembali']) ?></td><td><?php if($p['status']==='dipinjam'): ?><span class="badge badge-status bg-warning-subtle text-warning-emphasis">Dipinjam</span><?php else: ?><span class="badge badge-status bg-success-subtle text-success">Kembali</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div>
